def transform(grid):
    out = [row[:] for row in grid]
    values = sorted({v for row in grid for v in row})
    if len(values) < 2:
        return out

    mark, background = values[0], values[-1]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if (row[c] == background
                    and row[c - 1] == mark
                    and row[c + 1] == mark):
                out[r][c] = 2
    return out
